<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>游戏状态</title>
    <style>
        :root {
            --card-bg: rgba(255, 255, 255, 0.97);
            --text-primary: #333;
            --text-secondary: #777;
            --accent-color: #AEC6CF; /* 柔和的蓝灰色 */
            --border-color: #E0E0E0;
            --card-shadow: 0 4px 12px rgba(0, 0, 0, 0.08);
            --header-text-color: #FFFFFF;
        }

        body {
            background-color: transparent;
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
            color: var(--text-primary);
            margin: 0;
            padding: 8px;
            font-size: 14px;
            line-height: 1.5;
        }

        .status-container {
            background-color: var(--card-bg);
            border-radius: 12px;
            box-shadow: var(--card-shadow);
            overflow: hidden;
            max-width: 420px;
            margin: 0 auto;
            border: 1px solid var(--border-color);
        }

        .main-header {
            background-color: var(--accent-color);
            color: var(--header-text-color);
            padding: 12px 18px;
            text-align: center;
        }

        .main-header h2 {
            margin: 0;
            font-size: 1.3em;
            font-weight: 600;
        }

        .global-info-bar {
            display: flex;
            justify-content: space-around;
            align-items: center;
            padding: 10px 15px;
            font-size: 1em;
            color: var(--text-secondary);
            background-color: #F8F9FA;
            border-bottom: 1px solid var(--border-color);
        }
        .global-info-bar div {
            white-space: nowrap;
        }

        .characters-body {
            padding: 8px 0;
        }

        .character-section {
            border-bottom: 1px solid var(--border-color);
        }
        .character-section:last-child {
            border-bottom: none;
        }

        .section-toggle {
            padding: 10px 18px;
            cursor: pointer;
            display: flex;
            justify-content: space-between;
            align-items: center;
            font-size: 1.1em;
            font-weight: bold;
            transition: background-color 0.2s ease;
        }
        .section-toggle:hover {
            background-color: #F1F3F5;
        }
        .section-toggle .arrow {
            transition: transform 0.3s ease;
        }
        .section-toggle.expanded .arrow {
            transform: rotate(90deg);
        }

        .section-details {
            max-height: 0;
            overflow: hidden;
            transition: max-height 0.4s ease-in-out;
            padding: 0 18px;
            background-color: #FFFFFF;
        }

        .section-details.expanded {
            max-height: 2000px; /* A large value to allow content to expand */
            padding: 12px 18px 15px;
        }

        .attribute {
            display: flex;
            justify-content: space-between;
            align-items: baseline;
            margin-bottom: 6px;
            font-size: 0.95em;
        }
         .attribute:last-child {
             margin-bottom: 0;
         }

        .attribute-name {
            color: var(--text-secondary);
            margin-right: 10px;
            white-space: nowrap;
        }

        .attribute-value {
            font-weight: 500;
            text-align: right;
        }

        @media (max-width: 480px) {
            body {
                padding: 5px;
                font-size: 13px;
            }
            .status-container {
                border-radius: 10px;
            }
            .main-header {
                padding: 10px 15px;
            }
            .main-header h2 {
                 font-size: 1.2em;
            }
            .global-info-bar {
                font-size: 0.9em;
                padding: 8px 10px;
            }
            .section-toggle {
                padding: 9px 15px;
                font-size: 1em;
            }
            .section-details.expanded {
                 padding: 10px 15px 12px;
            }
            .attribute {
                font-size: 0.9em;
            }
        }
    </style>
</head>
<body>

