entries.content:
{
  "name": "瑞草洞4区",
  "parent_realm": "首尔特别市，瑞草区",
  "summary": "一个被都市更新计划割裂的区域。以正宇高等学校为界，北侧是被称为‘G-ONE塔’的新兴高级商住区，南侧则是尚未拆迁、被称为‘喜鹊村’的旧式住宅区。两个区域的居民共享同一所高中和少数商业设施，但除此之外几乎没有交集。一条宽阔的马路是两个世界间清晰的物理与心理边界。",
  "figures": [
    {
      "name": "李宰赫",
      "summary": "宇信集团会长的独子，正宇高等学校的风云人物。凭借家族势力在校内拥有特殊地位。"
    },
    {
      "name": "李彰元",
      "summary": "宇信集团会长。凭借强大的资本和政商关系，对瑞草洞4区的都市更新计划有直接影响力。"
    },
    {
      "name": "朴俊亨",
      "summary": "李宰赫的朋友，同样是财阀家庭出身，时常跟在李宰赫身边。"
    },
    {
      "name": "崔敏基",
      "summary": "李宰赫的朋友，性格更为冲动，是李宰赫在校内行动的执行者。"
    },
    {
      "name": "社区警卫",
      "summary": "负责G-ONE塔安保的人员，对业主和访客采取完全不同的态度。"
    },
    {
      "name": "便利店店员",
      "summary": "在学校附近便利店打工的年轻人，目睹着不同阶层的学生来来往往。"
    },
    {
      "name": "房产中介",
      "summary": "同时经手G-ONE塔和喜鹊村房产的本地中介，深谙两个区域的价值差异。"
    },
    {
      "name": "补习班老师",
      "summary": "在区域内开设补习班，其生源清楚地反映了阶层差异。"
    },
    {
      "name": "洗衣店老板",
      "summary": "在喜鹊村经营着一家小洗衣店，了解邻里间的琐事。"
    },
    {
      "name": "咖啡店主",
      "summary": "在G-ONE塔底层经营一家精品咖啡店，服务于富裕阶层。"
    },
    {
      "name": "家政服务员",
      "summary": "受雇于G-ONE塔的住户，每天穿梭于两个区域之间。"
    },
    {
      "name": "外卖配送员",
      "summary": "频繁出入两个区域，对地理环境非常熟悉。"
    },
    {
      "name": "学区家长A",
      "summary": "居住在G-ONE塔，热衷于子女的精英教育和人脉积累。"
    },
    {
      "name": "学区家长B",
      "summary": "居住在喜鹊村，为子女的学习成绩和未来感到焦虑。"
    },
    {
      "name": "退休老人",
      "summary": "常在喜鹊村的小公园里下棋，是社区的“活历史”。"
    },
    {
      "name": "健身教练",
      "summary": "G-ONE塔会所的私人教练，服务于高端客户。"
    },
    {
      "name": "区议员候选人",
      "summary": "在选举期间频繁出现在社区，对不同区域的居民做出不同的承诺。"
    },
    {
      "name": "教会牧师",
      "summary": "社区教会的负责人，其信众来自不同阶层。"
    },
    {
      "name": "流浪猫",
      "summary": "在喜鹊村的小巷中穿行，被一些居民偶尔投喂。"
    },
    {
      "name": "交通警察",
      "summary": "在学校门口的交通要道维持秩序，对不同牌照的车辆态度微妙。"
    }
  ],
  "locations": [
    {
      "name": "私立正宇高等学校",
      "summary": "由宇信集团等财阀出资建立的精英高中，是阶层分界的地理与社会中心。",
      "layout": "位于瑞草洞4区的中心，正门面向G-ONE塔，后门通往喜鹊村。"
    },
    {
      "name": "G-ONE塔顶层复式",
      "summary": "代表着财富与权力的顶级豪华住宅，拥有俯瞰整个区域的视野。",
      "layout": "位于瑞草洞4区北侧，是该新兴富人区的地标建筑。"
    },
    {
      "name": "喜鹊村半地下室",
      "summary": "象征着底层生活的狭窄潮湿的居所，位于旧住宅区的深处。",
      "layout": "位于瑞草洞4区南侧的旧住宅区内，与G-ONE塔遥遥相望。"
    }
  ]
}

